package universe

// V14ChainFrames returns the public bench v14 supersession-chain record frames
// (SN-353 / SN-354) by step kind, for the generator-inverse adversary
// (cmd/parserprobe). In each frame %[1]s is the subject phrase, %[2]s the
// value and %[3]s the copula ("is" or "is to"); revert frames carry only the
// subject. The frames are public, so the adversary reads them from here
// rather than keeping a copy that could drift; exporting them changes no
// generated bytes.
func V14ChainFrames() map[string][]string {
	clone := func(in []string) []string { return append([]string(nil), in...) }
	return map[string][]string{
		"plain":                clone(v14PlainForms),
		"announced":            clone(v14AnnouncedForms),
		"propose":              clone(v14ProposeForms),
		"propose-cued":         clone(v14ProposeCuedForms),
		"withdraw":             clone(v14WithdrawForms),
		"adopt":                clone(v14AdoptForms),
		"error":                clone(v14ErrorForms),
		"confirm":              clone(v14ConfirmForms),
		"revert-original":      clone(v14RevertOriginalForms),
		"revert-original-cued": clone(v14RevertOriginalCuedForms),
		"revert-previous":      clone(v14RevertPreviousForms),
		"revert-previous-cued": clone(v14RevertPreviousCuedForms),
	}
}
